package school.magiccodex.paper;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
import net.william278.husksync.HuskSync;import net.william278.husksync.redis.RedisManager;import net.william278.husksync.user.User;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class BagNativeRedisTest {
 static final class Fixture implements AutoCloseable {
  final ServerSocket server=new ServerSocket(0,1,InetAddress.getLoopbackAddress());final ExecutorService pool=Executors.newSingleThreadExecutor();final List<List<String>> commands=new CopyOnWriteArrayList<>();final Future<?> task;
  Fixture(String...values)throws Exception{task=pool.submit(()->{try(var socket=server.accept()){var in=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8));var out=socket.getOutputStream();for(String value:values){String start=in.readLine();int n=Integer.parseInt(start.substring(1));var command=new ArrayList<String>();for(int i=0;i<n;i++){in.readLine();command.add(in.readLine());}commands.add(command);if(value==null)out.write("$-1\r\n".getBytes());else{byte[] b=value.getBytes(StandardCharsets.UTF_8);out.write(("$"+b.length+"\r\n").getBytes());out.write(b);out.write(new byte[]{13,10});}out.flush();}}catch(Exception e){throw new CompletionException(e);}});}
  HuskSync husk(){var h=mock(HuskSync.class,RETURNS_DEEP_STUBS);var c=h.getSettings().getRedis().getCredentials();when(c.getHost()).thenReturn("127.0.0.1");when(c.getPort()).thenReturn(server.getLocalPort());when(c.getPassword()).thenReturn("");when(c.getUser()).thenReturn("");when(h.getSettings().getRedis().getSentinel().getNodes()).thenReturn(List.of());when(h.getSettings().getClusterId()).thenReturn("fixture");when(h.getServerName()).thenReturn("school");return h;}
  public void close()throws Exception{server.close();pool.shutdownNow();task.get(3,TimeUnit.SECONDS);}
 }
 @Test void destinationCheckoutIsNeverClearedAndNoLuaIsRequired()throws Exception{try(var f=new Fixture("wild")){var h=f.husk();var u=mock(User.class);when(u.getUuid()).thenReturn(UUID.randomUUID());try(var redis=new BagNativeRedis(h)){redis.releaseOwnCheckout(u);}assertEquals(1,f.commands.size());assertEquals("GET",f.commands.getFirst().getFirst());verify(h,never()).getRedisManager();}}
 @Test void ownCheckoutUsesNativeReleaseAndNonConsumingReadback()throws Exception{try(var f=new Fixture("school",null)){var h=f.husk();var called=new AtomicBoolean();var nativeRedis=new RedisManager(h){@Override public void setUserCheckedOut(User u,boolean checkedOut){assertFalse(checkedOut);called.set(true);}};doReturn(nativeRedis).when(h).getRedisManager();var u=mock(User.class);when(u.getUuid()).thenReturn(UUID.randomUUID());try(var redis=new BagNativeRedis(h)){redis.releaseOwnCheckout(u);}assertTrue(called.get());assertEquals(List.of("GET","GET"),f.commands.stream().map(x->x.getFirst()).toList());}}
 @Test void failedNativeReleaseKeepsTheFailureVisibleInsteadOfPretendingSuccess()throws Exception{try(var f=new Fixture("school","school")){var h=f.husk();var nativeRedis=new RedisManager(h){@Override public void setUserCheckedOut(User u,boolean checkedOut){}};doReturn(nativeRedis).when(h).getRedisManager();var u=mock(User.class);when(u.getUuid()).thenReturn(UUID.randomUUID());try(var redis=new BagNativeRedis(h)){assertThrows(IOException.class,()->redis.releaseOwnCheckout(u));}}}
}
